wrapper_template:
case "${1:-}" in
  query)
    [ -z "${2:-}" ] && { echo "Usage: supabase.sh query <sql>" >&2; exit 1; }
    psql "$DATABASE_URL" --csv -c "$2" | head -n "$MAX_LINES"
    ;;
  tables)
    psql "$DATABASE_URL" --csv -c "SELECT table_schema, table_name, table_type FROM information_schema.tables WHERE table_schema NOT IN ('pg_catalog','information_schema') ORDER BY table_schema, table_name" | head -n "$MAX_LINES"
    ;;
  schema)
    [ -z "${2:-}" ] && { echo "Usage: supabase.sh schema <table>" >&2; exit 1; }
    psql "$DATABASE_URL" --csv -c "\d $2" | head -n "$MAX_LINES"
    ;;
  extensions)
    psql "$DATABASE_URL" --csv -c "SELECT extname, extversion FROM pg_extension ORDER BY extname" | head -n "$MAX_LINES"
    ;;
  migrations)
    psql "$DATABASE_URL" --csv -c "SELECT * FROM supabase_migrations.schema_migrations ORDER BY version" 2>/dev/null | head -n "$MAX_LINES" || echo "No migrations table found"
    ;;
  migrate)
    [ -z "${2:-}" ] && { echo "Usage: supabase.sh migrate <sql>" >&2; exit 1; }
    psql "$DATABASE_URL" -c "$2"
    ;;
